import{z as l,x as o,o as e,c as n,q as i,j as r,D as a,d as A,s,S as B}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"卢卡斯批判","description":"","frontmatter":{"title":"卢卡斯批判","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lucas-critique.md","filePath":"econ/lucas-critique.md","lastUpdated":1791063341000}'),p={name:"econ/lucas-critique.md"};function c(d,E,C,h,D,_){const t=o("Mermaid");return e(),n("div",null,[E[2]||(E[2]=i('<h1 id="卢卡斯批判" tabindex="-1">卢卡斯批判 <a class="header-anchor" href="#卢卡斯批判" aria-label="Permalink to &quot;卢卡斯批判&quot;">​</a></h1><div class="epigraph"><p>政策一变，公众的决策规则就变；用旧制度下估出来的消费函数或菲利普斯曲线去模拟新政，是把简化式当成结构。</p><footer>—— Lucas, Econometric Policy Evaluation: A Critique, Carnegie–Rochester 1976</footer></div><p><a href="/econ/rbc-contrast">上一课</a>（真实经济周期对照）。在此之上，周期对照成：缺口可以是粘性，也可以是自然产出在动。两边都已经用到预期。本课的缺口不是再选 NK 或 RBC，而是：任何把 \\(C=cY\\)、把 Phillips 当固定菜单的计量政策评估，在规则改变时都会失效。Taylor 规则是下一课用显式利率规则去换「相机微调」；本课先把批判钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>战后宏观计量把消费、投资、工资方程估成对当期变量的回归，然后做「若 \\(G\\) 或 \\(M\\) 按某路径走，\\(Y\\) 如何」的模拟。Lucas（1976）指出：这些方程的系数里已经嵌着当时政策规则下的预期。规则一变，\\(\\pi^e\\)、持久收入、资本成本的推断都变，系数跟着变。缺口是区分<strong>结构参数</strong>（偏好、技术、调价频率）与<strong>简化式系数</strong>。</p><p><a href="/econ/phillips-expectations">菲利普斯</a>是最干净的例子：在固定 \\(\\pi^e\\) 下估出负斜率，用来选通胀–失业点；一旦央行改规则，\\(\\pi^e\\) 成为新规则的函数，替换消失。IS 的 \\(C(Y)\\) 同样：减税若被看成持久，MPC 大；若被看成李嘉图式的时间平移，MPC 小。用旧样本的 \\(c\\) 去乘新减税，是把预期制度偷运进乘数。</p><p><span class="marginnote">数字实例：同是 1 万元减税，家庭若相信是永久的，MPC 约 0.9、当年多花 9000；若相信是几年后要靠加税偿还的平移，MPC 近乎为 0。旧样本估出的单一 \\(c\\) 装不下这两种情形——乘数的差别全藏在预期制度里。</span></p><p><span class="marginnote">批判不是「计量无用」。它要求政策实验在均衡决策规则里做：改的是规则，解出的是新的欧拉与定价。校准与后来的 DSGE 是回应，不是免责。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把行为写成：最优决策是政策过程的函数。记规则为 \\(g\\)（例如 \\(M\\) 的反馈、利率如何对通胀反应）。简化式 \\(Y=A(g)X+\\varepsilon\\)。估计 \\(A(g_0)\\) 再代入 \\(g_1\\)，一般 \\(A(g_1)\\neq A(g_0)\\)。正确做法：从偏好与约束推导欧拉，把 \\(g\\) 放进预期，重新解均衡。</p>',10)),(e(),r(B,null,{default:a(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RED%5B%22%E7%AE%80%E5%8C%96%E5%BC%8F%EF%BC%9AC%3DcY%2C%20Phillips%22%5D%20--%3E%20G0%5B%22%E5%9C%A8%E8%A7%84%E5%88%99%20g0%20%E4%B8%8B%E4%BC%B0%E5%87%BA%22%5D%0A%20%20G0%20--%3E%20FAIL%5B%22%E4%BB%A3%E5%85%A5%20g1%EF%BC%9A%E7%B3%BB%E6%95%B0%E5%B7%B2%E5%8F%98%22%5D%0A%20%20STR%5B%22%E7%BB%93%E6%9E%84%EF%BC%9A%E5%81%8F%E5%A5%BD%E3%80%81%E6%8A%80%E6%9C%AF%E3%80%81%E7%B2%98%E6%80%A7%22%5D%20--%3E%20EQ%5B%22%E5%AF%B9%E6%96%B0%E8%A7%84%E5%88%99%E9%87%8D%E6%96%B0%E8%A7%A3%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=i('<p>Friedman 的自然率已经是批判的特例：货币规则不能把 \\(u\\) 永久钉在 \\(u^*\\) 下。Lucas 把它推广到所有「把历史相关当因果菜单」的做法。Hicks 的 IS–LM 比较静态若把 \\(P\\)、\\(\\pi^e\\) 当常数，同样犯简化式错误；若允许 \\(P\\) 与预期随规则调整，长期回到中性，与批判一致。</p><h3 id="识别仍要假设" tabindex="-1">识别仍要假设 <a class="header-anchor" href="#识别仍要假设" aria-label="Permalink to &quot;识别仍要假设&quot;">​</a></h3><p>声明结构不等于已经识别。NK 的 \\(\\kappa\\)、RBC 的冲击过程，都会随样本与设定而变。批判禁止的是无结构的政策模拟，不是保证某一个 DSGE 为真。</p><p>乘数 \\(dY/dG\\) 依赖 LM 斜率、粘性、是否李嘉图、规则是否对冲。把它当自然常数，正是批判的靶子。Hicks 图仍可用于既定规则下的叙事，但不能当新政计算器。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预期是对未来政策的条件期望。家庭与厂商的欧拉、调价，把这些期望编进当前的 \\(C\\)、\\(P\\)、\\(w\\)。计量若只回归当前 \\(Y\\) 与 \\(\\pi\\)，等于把期望压缩进系数。新政改变期望的信息集，压缩结果不同。时间不一致课会再加一层：连「宣布的规则」本身都可能不可信，期望对准的是将来会重新优化的那条路径。</p><p><span class="marginnote">术语翻译：「结构参数」是不随政策规则变的深层性质——偏好、技术、调价频率；「简化式系数」是历史数据里估出的共动（如 \\(C=cY\\) 的 \\(c\\)）。批判的一句话版：只有前者有资格回答「如果政策变了会怎样」。</span></p>',7)),(e(),r(B,null,{default:a(()=>[s(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAMEG%5B%22%E8%A7%84%E5%88%99%E4%B8%8D%E5%8F%98%3A%20%E9%A2%84%E6%9C%9F%E5%B7%B2%E9%80%82%E5%BA%94%20g0%22%5D%20--%3E%20OKF%5B%22%E7%AE%80%E5%8C%96%E5%BC%8F%E5%8F%AF%E4%BB%A5%E9%A2%84%E6%8A%A5%E4%B8%8B%E4%B8%80%E5%AD%A3%22%5D%0A%20%20NEWG%5B%22%E5%AE%A3%E5%B8%83%E6%96%B0%E8%A7%84%E5%88%99%20g1%22%5D%20--%3E%20FORM%5B%22%E5%85%AC%E4%BC%97%E9%87%8D%E6%96%B0%E5%BD%A2%E6%88%90%E9%A2%84%E6%9C%9F%22%5D%0A%20%20FORM%20--%3E%20BEHAVE%5B%22%E6%B6%88%E8%B4%B9%E4%B8%8E%E5%AE%9A%E4%BB%B7%E8%A1%8C%E4%B8%BA%E8%B7%9F%E7%9D%80%E5%8F%98%22%5D%0A%20%20BEHAVE%20--%3E%20COEF%5B%22%E7%AE%80%E5%8C%96%E5%BC%8F%E7%B3%BB%E6%95%B0%20A%20%E9%9A%8F%E8%A7%84%E5%88%99%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20COEF%20--%3E%20NOPE%5B%22%E6%97%A7%E7%B3%BB%E6%95%B0%E4%B8%8D%E8%83%BD%E5%BD%93%E6%96%B0%E6%94%BF%E7%AD%96%E7%9A%84%E8%AE%A1%E7%AE%97%E5%99%A8%22%5D%0A%20%20STRUCT%5B%22%E7%BB%93%E6%9E%84%3A%20%E5%81%8F%E5%A5%BD%E6%8A%80%E6%9C%AF%E7%BA%A6%E6%9D%9F%E4%B8%8D%E9%9A%8F%E8%A7%84%E5%88%99%E5%8F%98%22%5D%20--%3E%20RESOLVE%5B%22%E5%AF%B9%E6%96%B0%E8%A7%84%E5%88%99%E9%87%8D%E8%A7%A3%E5%9D%87%E8%A1%A1%E6%89%8D%E8%83%BD%E8%AF%84%E4%BC%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=i('<p>Kydland–Prescott 的 RBC 校准与 Woodford 的 NK，都是对批判的建设性回应：先写对规则不变的块，再改 \\(g\\) 解新均衡。IS–LM 比较静态若把 \\(P\\) 与 \\(\\pi^e\\) 冻住，是批判的靶子；若允许二者随规则走，长期中性与自然率重新出现，与 Friedman 1968 一致。</p><p><span class="marginnote">规则不变时，简化式可以预报下一季 \\(Y\\)。批判禁止的是把预报方程当成「若改 \\(g\\) 会怎样」的实验室。预测与评估不是同一句话。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>批判不自动支持「政策完全无效」。在粘性价格下，被理解的规则仍然通过实际利率路径改变 \\(\\tilde{y}\\)——那是结构模拟，不是旧 Phillips 菜单。也不要把批判写成「任何回归都不能做预测」：在规则不变时，简化式可以预测；变的是<strong>政策评估</strong>。</p><p>识别失败仍可能发生：深层 \\(\\theta\\) 估错，新规则下的模拟一样错。批判是必要条，不是充分条。本栏不把批判延伸成高频交易策略的参数漂移；那是量化栏的另一套不变性。</p><p>后课默认：谈乘数、泰勒规则、承诺，必须说清规则与预期如何进入结构。下一课把利率政策写成对通胀与缺口的反应函数。</p><p><span class="marginnote">常见误区：初学者容易把批判读成「回归无用」或「政策无效」——规则不变时简化式照样能预报；粘性价格下被理解的新规则仍可通过实际利率改变产出。批判禁止的只有一件事：拿旧系数当新政策的计算器。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>简化式系数嵌着旧规则下的预期，不能直接用来评估新政。</li><li>结构是偏好、技术、约束与定价摩擦；政策是规则 \\(g\\)。</li><li>Phillips 菜单与 \\(C=cY\\) 乘数是典型翻车处。</li><li>正确做法是对新规则解均衡，不是平移历史回归。</li><li>预报可以靠简化式；评估不能。</li><li>出处：Lucas, Carnegie–Rochester 1976。</li></ul>',9))])}const F=l(p,[["render",c]]);export{m as __pageData,F as default};
